-- GENERATED by scripts/generate-seed.ts — do not edit by hand.
-- Fictional RH PC LAB game data (not official Computers RH items).

on conflict (id) do update set
  name = excluded.name, category = excluded.category, rarity = excluded.rarity, price = excluded.price,
  performance = excluded.performance, power = excluded.power, description = excluded.description, metadata = excluded.metadata;

on conflict (id) do update set
  name = excluded.name, description = excluded.description, icon = excluded.icon,
  requirement_type = excluded.requirement_type, requirement_value = excluded.requirement_value;

-- One challenge per UTC day, rotating through the templates by day index
-- (matches challengeForDate() in lib/pc-engine/challenges.ts).
with templates (idx, title, description, rules) as (values
  (0, 'BUILD UNDER $2,000', 'Squeeze the most score out of a tight budget.', '{"maxBudget":2000,"minRamGb":16,"requiredCategories":["gpu"]}'::jsonb),
  (1, 'MAXIMUM PERFORMANCE', 'No budget limit. Highest score wins.', '{}'::jsonb),
  (2, 'ENERGY EFFICIENT', 'Keep total power draw at 500W or below.', '{"maxPower":500}'::jsonb),
  (3, 'SMALL BUT MIGHTY', 'Build inside a MINI case and still score 60+.', '{"caseSize":"MINI","minScore":60}'::jsonb),
  (4, 'COMMON GROUND', 'Nothing above RARE allowed. Pure skill.', '{"maxRarity":"RARE"}'::jsonb),
  (5, 'MEMORY LANE', '64GB of RAM or more, total value under $3,500.', '{"minRamGb":64,"maxBudget":3500}'::jsonb),
  (6, 'RETRO NIGHT', 'Use the RetroBox case or the RetroTube CRT. Vibes first.', '{"requireAnyOf":["case-retrobox","mon-retrotube-17"]}'::jsonb)
)
select to_char(d, 'YYYY-MM-DD'), t.title, t.description, t.rules, d::date, d::date
from generate_series(date '2026-01-01', date '2028-12-31', interval '1 day') as d
join templates t on t.idx = ((d::date - date '1970-01-01') % 7)
on conflict (id) do nothing;
